 {
     for (const ir::AstNode *node = expr; node != nullptr && !node->IsClassDefinition(); node = node->Parent()) {
         if (node->IsClassProperty() && IsNotInStructFieldInitializer(node)) {
             return true;
         }
     }
     return false;
 }

