+static void CheckUnreachableOverload(ETSChecker *checker, ir::OverloadDeclaration *node)
+{
+    auto &overloadedList = node->OverloadedList();
+
+    for (size_t i = 1; i < overloadedList.size(); ++i) {
+        auto *currentType = overloadedList[i]->TsType();
+        if (currentType == nullptr || !currentType->IsETSFunctionType()) {
+            continue;
+        }
+
+        auto *currentFuncType = currentType->AsETSFunctionType();
+        for (auto *currentSig : currentFuncType->CallSignatures()) {
+            const Signature *coveringSig = FindCoveringSignature(checker, currentSig, overloadedList, i);
+            if (coveringSig != nullptr) {
+                auto currentSigName = currentSig->Function()->Id()->Name();
+                auto coveringSigName = coveringSig->Function()->Id()->Name();
+                checker->LogError(diagnostic::OVERLOAD_UNREACHABLE_WARNING, {currentSigName, coveringSigName},
+                                  overloadedList[i]->Start());
+                break;
+            }
+        }
+    }
+}
