 bool TypeRelation::CheckTypeParameterConstraints(ArenaVector<Type *> const &typeParameters1,
                                                  ArenaVector<Type *> const &typeParameters2)
 {
     auto const paramNumber = typeParameters1.size();
     if (paramNumber != typeParameters2.size()) {
         return false;
     }

     if (paramNumber > 0U) {
         for (std::size_t i = 0U; i < paramNumber; ++i) {
             auto const *const c1 = typeParameters1[i]->AsETSTypeParameter()->GetConstraintType();
             auto const *const c2 = typeParameters2[i]->AsETSTypeParameter()->GetConstraintType();
             if (!IsSupertypeOf(c1, c2)) {  // contravariance check
                 return false;
             }
         }
     }
     return true;
 }

 bool TypeRelation::IsIdenticalTo(Type *source, Type *target)
 {
     if (source == nullptr || target == nullptr) {
         return Result(false);
     }

     if (source == target) {
         return Result(true);
     }

     result_ = CacheLookup(source, target, checker_->IdenticalResults(), RelationType::IDENTICAL);
     if (result_ == RelationResult::CACHE_MISS) {
         checker_->ResolveStructuredTypeMembers(source);
         checker_->ResolveStructuredTypeMembers(target);
         result_ = RelationResult::FALSE;
         target->Identical(this, source);
         auto key = RelationHolder::MakeKey(source->Id(), target->Id());
         checker_->IdenticalResults().Insert(key, {result_, RelationType::IDENTICAL});
     }

     return IsTrue();
 }

 bool TypeRelation::SignatureIsIdenticalTo(Signature const *source, Signature const *target)
 {
     if (source == target) {
         return Result(true);
     }

     Result(false);
     if (target->IsSubtypeOf(this, source), IsTrue()) {
         if (source->IsSubtypeOf(this, target), IsTrue()) {
             return Result(true);
         }
     }
     return Result(false);
 }

 bool TypeRelation::SignatureIsSupertypeOf(Signature const *super, Signature const *sub)
 {
     if (super == sub) {
         return Result(true);
     }

     Result(false);
     sub->IsSubtypeOf(this, super);
     return IsTrue();
 }

